using System;using System.Collections.Generic;using System.IO;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;
namespace Dafeiyu {
// One owner per application data root. Only unsent text is stored; no conversation history is created.
public sealed class ComposerDraftStore:IDisposable {
readonly object gate=new object();readonly string directory;readonly Dictionary<string,string> pending=new Dictionary<string,string>();readonly HashSet<string> blocked=new HashSet<string>();Timer timer;bool disposed;readonly Dafeiyu.Maintenance.DataMaintenanceGate maintenance;readonly IDisposable registration;
public string Warning {get;private set;}public event Action WarningChanged;
public ComposerDraftStore(string root,Dafeiyu.Maintenance.DataMaintenanceGate gate=null){directory=Path.Combine(root,"composer-drafts");maintenance=gate??new Dafeiyu.Maintenance.DataMaintenanceGate();registration=maintenance.Register(()=>{Flush();return System.Threading.Tasks.Task.FromResult(0);},owner:this);}
public static string Scope(string role,string mode,string project,string section){return new JavaScriptSerializer().Serialize(new[]{role??"",mode??"",project??"",section??""});}
string FileName(string scope){using(var sha=SHA256.Create())return Path.Combine(directory,BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(scope))).Replace("-","").ToLowerInvariant()+".draft");}
void Fail(){Warning=TextResources.Get("composerDraft.storageError");var changed=WarningChanged;if(changed!=null)changed();}
public string Get(string scope){lock(gate){string value;if(pending.TryGetValue(scope,out value))return value;string path=FileName(scope);try{Dafeiyu.Maintenance.CachePaths.Check(path);if(!File.Exists(path))return "";var info=new FileInfo(path);if(info.Length>4*1024*1024)throw new InvalidDataException();var bytes=SecretProtection.Unprotect(File.ReadAllBytes(path));if(bytes.Length>2*1024*1024)throw new InvalidDataException();var data=new JavaScriptSerializer{MaxJsonLength=2*1024*1024,RecursionLimit=8}.Deserialize<Dictionary<string,string>>(new UTF8Encoding(false,true).GetString(bytes));if(data["version"]!="1"||data["scope"]!=scope)throw new InvalidDataException();return data["text"]??"";}catch(Exception ex){if(!StorageError(ex))throw;blocked.Add(scope);Fail();return "";}}}
public void Set(string scope,string text){IDisposable activity;if(!maintenance.TryEnterActivity(out activity))return;using(activity)lock(gate){if(disposed)return;if(blocked.Contains(scope)){Fail();return;}text=text??"";if(Encoding.UTF8.GetByteCount(text)>1024*1024){Fail();return;}pending[scope]=text;if(timer==null)timer=new Timer(_=>Flush(),null,350,Timeout.Infinite);else timer.Change(350,Timeout.Infinite);}}
public void Flush(){lock(gate){foreach(var item in new List<KeyValuePair<string,string>>(pending)){string path=FileName(item.Key),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{Dafeiyu.Maintenance.CachePaths.Check(path);Directory.CreateDirectory(directory);if(item.Value.Length==0){if(File.Exists(path))File.Delete(path);}else{var json=new JavaScriptSerializer().Serialize(new Dictionary<string,string>{{"version","1"},{"scope",item.Key},{"text",item.Value}});var cipher=SecretProtection.Protect(Encoding.UTF8.GetBytes(json));using(var file=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(cipher,0,cipher.Length);file.Flush(true);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}pending.Remove(item.Key);if(pending.Count==0&&blocked.Count==0)Warning=null;}catch(Exception ex){if(!StorageError(ex))throw;Fail();}finally{try{if(File.Exists(temp))File.Delete(temp);}catch(IOException){}catch(UnauthorizedAccessException){}}}}}
static bool StorageError(Exception ex){return ex is IOException||ex is UnauthorizedAccessException||ex is CryptographicException||ex is InvalidOperationException||ex is ArgumentException||ex is KeyNotFoundException||ex is System.Runtime.Serialization.SerializationException;}
public void Dispose(){lock(gate){if(disposed)return;Flush();disposed=true;if(timer!=null)timer.Dispose();registration.Dispose();}}
}}
